trait CustomerDao {
  def find(id: Long): Option[Customer]                      // case class result
  def add(c: Customer): Either[DaoError, Unit]
}
final class JdbcCustomerDao(ds: DataSource) extends CustomerDao {
  def find(id: Long): Option[Customer] = withConnection { conn =>
    val ps = conn.prepareStatement("SELECT id, name FROM customer WHERE id = ?")
    ps.setLong(1, id)
    val rs = ps.executeQuery()
    if (rs.next()) Some(Customer(rs.getLong("id"), rs.getString("name"))) else None
  }                                                         // driver errors -> DaoError
}

